fk=lambda a,b:(math.cos(a)+math.cos(a+b),math.sin(a)+math.sin(a+b));distance=lambda a,b:math.hypot(a[0]-b[0],a[1]-b[1]);z=[(a-b)/s for a,b,s in zip([2.5,1400,45],[2,1500,40],[.5,100,5])];k=[math.exp(-math.log(2)/3*sum((a-b)**2 for a,b in zip(z,v))) for v in [[1,-1,1],[0,0,0]]];score=2*k[0]-k[1]-1.25
