 j11=-math.sin(a)-math.sin(a+b);j12=-math.sin(a+b);j21=math.cos(a)+math.cos(a+b);j22=math.cos(a+b);assert math.isclose(j11*j22-j12*j21,math.sin(b),abs_tol=1e-12)
 values=[rng.uniform(-10,10) for i in range(3)];scale=[rng.uniform(.01,5) for i in range(3)];mu=[rng.uniform(-5,5) for i in range(3)];zs=[(v-m)/s for v,m,s in zip(values,mu,scale)];assert all(math.isclose(z*s+m,v,abs_tol=1e-12) for z,s,m,v in zip(zs,scale,mu,values))
 u,v=rng.uniform(0,1),rng.uniform(0,1);n,m=rng.randint(1,100),rng.randint(1,100);weighted=(n*u+m*v)/(n+m);assert min(u,v)-1e-12<=weighted<=max(u,v)+1e-12
